<script setup lang="ts">
import * as v from 'valibot'
definePageMeta({ layout: 'admin', middleware: 'admin-auth' })
const api = useAdminApi(); const toast = useToast(); const state = reactive({ currentPassword: '', newPassword: '', confirm: '' }); const pending = ref(false)
const schema = v.object({ currentPassword: v.pipe(v.string(), v.minLength(1, '请输入当前密码')), newPassword: v.pipe(v.string(), v.minLength(8, '新密码至少 8 位')), confirm: v.pipe(v.string(), v.minLength(8, '请确认新密码')) })
async function save() { if (state.newPassword !== state.confirm) return toast.add({ title: '两次输入的新密码不一致', color: 'error' }); pending.value = true; try { await api.post('auth/change-password', { currentPassword: state.currentPassword, newPassword: state.newPassword }); toast.add({ title: '密码已更新', color: 'success' }); Object.assign(state, { currentPassword: '', newPassword: '', confirm: '' }) } catch { toast.add({ title: '密码更新失败', color: 'error' }) } finally { pending.value = false } }
</script><template><div class="max-w-lg space-y-5"><div><p class="text-sm text-muted">账户安全</p><h2 class="text-2xl font-semibold">修改密码</h2></div><UCard><UForm :schema="schema" :state="state" class="space-y-4" @submit="save"><UFormField label="当前密码" name="currentPassword"><UInput v-model="state.currentPassword" type="password" class="w-full" /></UFormField><UFormField label="新密码" name="newPassword"><UInput v-model="state.newPassword" type="password" class="w-full" /></UFormField><UFormField label="确认新密码" name="confirm"><UInput v-model="state.confirm" type="password" class="w-full" /></UFormField><UButton type="submit" :loading="pending">更新密码</UButton></UForm></UCard></div></template>
